interface CartElement extends HTMLElement {
  addItem: (id: string, quantity?: number) => void;
}

class UpsellBlock extends HTMLElement {
  private button: HTMLButtonElement | null = null;

  connectedCallback() {
    this.button = this.querySelector<HTMLButtonElement>(".button");
    if (!this.button) return;
    this.button.addEventListener("click", this.handleClick);
  }

  disconnectedCallback() {
    this.button?.removeEventListener("click", this.handleClick);
  }

  private handleClick = () => {
    if (!this.button) return;

    const variantId = this.button.dataset.variantId;
    const qty = parseInt(this.button.dataset.quantity || "1", 10);

    if (!variantId) {
      console.error("UpsellBlock: No variant id provided");
      return;
    }

    const cartEl = document.querySelector<CartElement>("uwp-cart");
    if (!cartEl?.addItem) {
      console.error(
        "UpsellBlock: uwp-cart element not found or addItem not available",
      );
      return;
    }

    cartEl.addItem(variantId, qty);

    // If action triggered from minicart, scroll to top and hide upsells
    const minicartOpen = document.querySelector(".minicart__drawer.is-open");
    if (minicartOpen) {
      const scrollContainer = document.querySelector<HTMLElement>(
        ".minicart__body-wrapper",
      );
      scrollContainer?.scrollTo({ top: 0, behavior: "smooth" });

      const upsellsEl =
        document.querySelector<HTMLElement>(".minicart__upsells");
      if (upsellsEl) {
        upsellsEl.style.display = "none";
        upsellsEl.setAttribute("aria-hidden", "true");
      }
    }

    if (document.body.classList.contains("template-cart")) {
      // give Shopify a moment to update then refresh
      setTimeout(() => {
        window.location.reload();
      }, 500);
    }
  };
}

customElements.define("uwp-upsell-block", UpsellBlock);
